  ["ce973e47"] = "Класове завдання шамана з 30-го рівня; відкривається попереднім завданням шамана (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал у локації «{zone:Thousand Needles}».",
  ["d303a745"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:Razorfen Kraul}»",
  ["fa5abda0"] = "Класове завдання шамана з 30-го рівня; відкривається попереднім завданням шамана (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал у локації «{zone:Thousand Needles}». Хто з НІП Орди видає завдання після підземелля, ще не підтверджено («{npc:Prate Cloudseer}» або «{npc:Rau Cliffrunner}»): дивіться журнал завдань.",
  ["dd1d6df1"] = "Зачекайте, поки «{npc:Furen Longbeard}» закінчить вашу броню.",
  ["f23278cc"] = "Класове завдання воїна з 20-го рівня. У цьому підземеллі: для завдання «{quest:Fire Hardened Mail}» потрібен предмет «{item:Vial of Phlogiston}» від «{npc:Roogug}», першого боса. Після завдання «{quest:Fire Hardened Mail}» НІП «{npc:Grimand Elmore}» («{zone:Stormwind}»), «{npc:Klockmort Spannerspan}» («{zone:Ironforge}») і ще один НІП («{zone:Darnassus}») виготовляють ще по одній частині:",
  ["b58a5bc5"] = "Зачекайте, поки «{npc:Thun'grim Firegaze}» закінчить вашу броню.",
  ["06f50add"] = "Класове завдання воїна з 20-го рівня. У цьому підземеллі: для завдання «{quest:Brutal Armor}» потрібен предмет «{item:Vial of Phlogiston}» від «{npc:Roogug}», першого боса. Після завдання «{quest:Brutal Armor}» ще один НІП, «{npc:Orm Stonehoof}» («{zone:Thunder Bluff}») і «{npc:Velora Nitely}» виготовляють ще по одній частині:",
  ["11b3361f"] = "Прочитайте предмет «{item:Henrig Lonebrow's Journal}» і віднесіть його до НІП «{npc:Falfindel Waywarder}» у місцевості «{zone:Thalanaar}».",
  ["f93aac54"] = "Потрібне перед завданням «{quest:The Crone of the Kraul}».",
  ["c045f5f4"] = "Увійдіть до печер «{zone:Rethban Caverns}», дійдіть до першої розвилки й вчасно поверніться до НІП «{npc:Yorus Barleybrew}». Не можна загинути й відпустити дух.",
  ["c11c3a7d"] = "Ваш наставник воїнів («{npc:Wu Shen}» у місті «{zone:Stormwind}» або наставники в містах «{zone:Ironforge}» і «{zone:Darnassus}») спершу відправляє вас до НІП «{npc:Yorus Barleybrew}» у місцевості «{zone:Lakeshire}». Проходження обмежене в часі.",
  ["910d2d0d"] = "Зберіть матеріали, потрібні НІП «{npc:Furen Longbeard}», і принесіть їх йому в місто «{zone:Stormwind}».",
