  ["fd4f34ea"] = "Поговоріть з НІП «{npc:Thun'grim Firegaze}» у локації «{zone:The Barrens}».",
  ["a8d67620"] = "Принесіть до НІП «{npc:Thun'grim Firegaze}» «{item:Smoky Iron Ingot}»: 15 шт., «{item:Powdered Azurite}»: 10 шт., «{item:Iron Bar}»: 10 шт. і предмет «{item:Vial of Phlogiston}».",
